import{_ as e,c as o,o as c,Q as t}from"./chunks/framework.5f28ab71.js";const T=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"compiler/设计原则/5-小结.md","lastUpdated":1724243587000}'),d={name:"compiler/设计原则/5-小结.md"},r=t("<p>了解 <code>compiler</code> 的整体编译设计原则。</p><p>我们知道，整个 <code>compiler</code> 的过程，就是一个把：<strong>源代码（<code>template</code>）转化为目标代码（<code>render</code> 函数）</strong> 的过程。</p><p>在这个过程中，主要经历了三个大的步骤：</p><ol><li>解析（ <code>parse</code> ） <code>template</code> 模板，生成 <code>AST</code></li><li>转化（<code>transform</code>）<code>AST</code>，得到 <code>JavaScript AST</code></li><li>生成（<code>generate</code>）<code>render</code> 函数</li></ol><p>这三步是非常复杂的一个过程，内部的实现涉及到了非常复杂的计算方法，并且会涉及到一些我们现在还没有了解过得概念，比如：<strong>自动状态机</strong>。</p>",5),a=[r];function _(p,s,n,i,l,m){return c(),o("div",null,a)}const f=e(d,[["render",_]]);export{T as __pageData,f as default};
